# ATELIER HUDA V6 — paste into PowerShell and Enter
$ErrorActionPreference = 'Stop'
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$repoUrl = 'https://github.com/ex-experience/huda.atelier.git'
$dest = Join-Path $env:USERPROFILE 'huda.atelier'
if (Test-Path (Join-Path $dest '.git')) {
  Set-Location $dest
  git pull origin main
} else {
  if (Test-Path $dest) { Remove-Item $dest -Recurse -Force }
  git clone $repoUrl $dest
  Set-Location $dest
}
New-Item -ItemType Directory -Force -Path 'assets\js','assets\css','supabase' | Out-Null
function Write-Utf8($Path, $Text) {
  $full = Join-Path (Get-Location) $Path
  New-Item -ItemType Directory -Force -Path ([IO.Path]::GetDirectoryName($full)) | Out-Null
  [IO.File]::WriteAllText($full, $Text, [Text.UTF8Encoding]::new($false))
}
